<?php
use PHPUnit\Framework\TestCase;
final class Phase9PMAgreementsTest extends TestCase {
 public function test_pm_agreement_upgrade_is_versioned_and_normalized(): void {$b=file_get_contents(__DIR__.'/../../servsys.php');$s=file_get_contents(__DIR__.'/../../src/Database/Schema.php');preg_match("/SERVSYS_DB_VERSION',\\s*(\\d+)/",$b,$m);$this->assertGreaterThanOrEqual(13,(int)($m[1]??0));$this->assertStringContainsString('servsys_pm_agreements',$s);$this->assertStringContainsString('servsys_pm_agreement_equipment',$s);$this->assertStringNotContainsString('enum1',$s);$this->assertStringNotContainsString('enum10',$s);$this->assertStringNotContainsString('visit1',$s);}
 public function test_agreement_schema_snapshots_contract_commercial_data(): void {$s=file_get_contents(__DIR__.'/../../src/Database/Schema.php');foreach(array('contract_price decimal(13,4)','plan_description_snapshot varchar(255)','plan_tm_estimate_snapshot decimal(13,4)','term_months smallint(5)','visits_per_year smallint(5)','additional_services longtext','status varchar(20)') as $field){$this->assertStringContainsString($field,$s);}}
 public function test_covered_equipment_is_unlimited_normalized_junction(): void {$s=file_get_contents(__DIR__.'/../../src/Database/Schema.php');$this->assertStringContainsString('UNIQUE KEY agreement_equipment (pm_agreement_id,equipment_id)',$s);$this->assertStringContainsString('equipment_id bigint(20) unsigned NOT NULL',$s);}
 public function test_agreement_service_enforces_company_customer_site_plan_and_equipment_chain(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMAgreementService.php');foreach(array('Customer does not belong to the current company','Site must belong to the selected Customer and current company','PM Plan does not belong to the current company','Selected PM Plan term is invalid','Covered Equipment must belong to the Agreement Site and Customer') as $message){$this->assertStringContainsString($message,$p);}}
 public function test_agreement_service_snapshots_plan_and_term_price(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMAgreementService.php');$this->assertStringContainsString("'contract_price'=>(float)\$term['price']",$p);$this->assertStringContainsString("'plan_description_snapshot'=>\$plan['description']",$p);$this->assertStringContainsString("'plan_tm_estimate_snapshot'=>(float)\$plan['tm_estimate']",$p);}
 public function test_covered_equipment_replacement_is_atomic(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMAgreementService.php');$this->assertStringContainsString('START TRANSACTION',$p);$this->assertStringContainsString('ROLLBACK',$p);}
 public function test_pm_agreement_capabilities_are_company_scoped(): void {$c=file_get_contents(__DIR__.'/../../src/Users/Capabilities.php');$this->assertStringContainsString("VIEW_PM_AGREEMENTS = 'servsys_view_pm_agreements'",$c);$this->assertStringContainsString("MANAGE_PM_AGREEMENTS = 'servsys_manage_pm_agreements'",$c);$this->assertGreaterThanOrEqual(2,substr_count($c,'self::VIEW_PM_AGREEMENTS'));$this->assertGreaterThanOrEqual(2,substr_count($c,'self::MANAGE_PM_AGREEMENTS'));}
 public function test_admin_requires_nonce_and_manage_permission(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/PMAgreementsPage.php');$this->assertStringContainsString("check_admin_referer('servsys_save_pm_agreement')",$p);$this->assertStringContainsString('Capabilities::MANAGE_PM_AGREEMENTS',$p);$this->assertStringContainsString('Covered Equipment',$p);}
 public function test_agreement_repositories_are_company_scoped(): void {foreach(array('PMAgreementRepository.php','PMAgreementEquipmentRepository.php') as $file){$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/'.$file);$this->assertStringContainsString('CompanyContext::current_company_id()',$p,$file);}}
}
